INSERT INTO `table_extensions` VALUES (1,'Tháng 10 này, công ty Sona mang đến cho quý khách hàng những ưu đãi đặc biệt không thể bỏ lỡ!\r\n1. Giảm Giá Đặc Biệt Cho Sản Phẩm Mới\r\nGiảm giá 20% cho tất cả các sản phẩm mới ra mắt trong tháng 10.\r\nƯu đãi thêm 10% khi mua từ 2 sản phẩm trở lên.\r\n2. Quà Tặng Hấp Dẫn\r\nTặng ngay voucher mua hàng trị giá 200.000 VND cho mỗi đơn hàng từ 1.000.000 VND.\r\nCơ hội nhận quà tặng đặc biệt khi mua hàng vào các ngày cuối tuần.\r\nThời Gian Áp Dụng\r\nChương trình khuyến mãi diễn ra từ 01/10 đến 31/10/2024.\r\nHãy nhanh tay đến với Sona để tận hưởng những ưu đãi tuyệt vời này. Chúng tôi luôn sẵn sàng phục vụ và mang đến cho quý khách hàng những trải nghiệm mua sắm tốt nhất.','Khuyến mãi tháng 5','Chương Trình Khuyến Mãi Tháng 10 của Công Ty Sona','Khuyến mãi tháng 5',NULL,NULL,'','','hop-banh-trung-thu-lam-nguyet-phu-quy-1729824774.jpg','{\"type\":\"1\",\"popup\":\"popup1\",\"fullname\":\"fullname\",\"hotline\":\"hotline\",\"address\":\"address\",\"email\":\"email\",\"content\":\"content\",\"background\":\"9ACD32\",\"color-title\":\"FFFFFF\",\"color-send\":\"FFFFFF\",\"background-send\":\"FF0000\"}','popup','','2024-10-25 17:06:07',NULL),(2,NULL,NULL,'Hotline','Hotline','0334567899','0399413032',NULL,NULL,'callphone-1726214231-1726447808.png','{\"hotline\":\"hotline1\",\"background\":\"3366CC\",\"background-text\":\"FFFF66\",\"color\":\"000000\",\"destop\":{\"device\":\"on\",\"left\":\"0\",\"right\":\"20\",\"bottom\":\"120\"},\"mobile\":{\"left\":\"0\",\"right\":\"20\",\"bottom\":\"120\"}}','hotline','hienthi','2024-11-01 17:53:42','2024-05-03 01:50:01'),(4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{\"social1\":{\"status\":\"on\",\"background\":\"3366CC\",\"color\":\"FFFFFF\",\"destop\":{\"device\":\"on\",\"left\":\"0\",\"right\":\"20\",\"bottom\":\"200\"},\"mobile\":{\"left\":\"0\",\"right\":\"20\",\"bottom\":\"200\"}},\"social2\":{\"status\":\"on\",\"background\":\"3DFF99\",\"color\":\"FFE3F2\",\"destop\":{\"left\":\"0\",\"right\":\"0\",\"bottom\":\"10\"},\"mobile\":{\"left\":\"0\",\"right\":\"0\",\"bottom\":\"10\"}}}','social','hienthi','2024-11-04 02:54:29','2024-05-06 08:25:52');
