e3c s\\u1eafp x\\u1ebfp tinh t\\u1ebf b\\u00ean trong. H\\u00e3y c\\u1ea9n th\\u1eadn \\u0111\\u1ec3 kh\\u00f4ng l\\u00e0m h\\u01b0 h\\u1ea1i h\\u1ed9p v\\u00e0 c\\u00e1c s\\u1ea3n ph\\u1ea9m.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;6:1-7:0&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;C\\u00f3 th\\u1ec3 gi\\u1eef l\\u1ea1i h\\u1ed9p qu\\u00e0 \\u0111\\u1ec3 tr\\u01b0ng b\\u00e0y, \\u0111\\u1ef1ng \\u0111\\u1ed3 ho\\u1eb7c t\\u00e1i s\\u1eed d\\u1ee5ng v\\u1edbi c\\u00e1c m\\u1ee5c \\u0111\\u00edch kh\\u00e1c.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n&lt;\\/ul&gt;\\r\\n\\r\\n&lt;p data-sourcepos=&quot;8:1-8:24&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;strong&gt;2. S\\u1eed d\\u1ee5ng s\\u1ea3n ph\\u1ea9m:&lt;\\/strong&gt;&lt;\\/span&gt;&lt;\\/p&gt;\\r\\n\\r\\n&lt;ul data-sourcepos=&quot;10:1-15:0&quot;&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;10:1-10:91&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;strong&gt;Tr\\u00e0:&lt;\\/strong&gt; Pha tr\\u00e0 theo h\\u01b0\\u1edbng d\\u1eabn tr\\u00ean bao b\\u00ec. C\\u00f3 th\\u1ec3 th\\u01b0\\u1edfng th\\u1ee9c n\\u00f3ng ho\\u1eb7c l\\u1ea1nh t\\u00f9y th\\u00edch.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;11:1-11:82&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;strong&gt;C\\u00e0 ph\\u00ea:&lt;\\/strong&gt; Pha phin ho\\u1eb7c s\\u1eed d\\u1ee5ng m\\u00e1y pha c\\u00e0 ph\\u00ea \\u0111\\u1ec3 c\\u00f3 \\u0111\\u01b0\\u1ee3c ly c\\u00e0 ph\\u00ea th\\u01a1m ngon.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;12:1-12:129&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;strong&gt;B\\u00e1nh k\\u1eb9o healthy:&lt;\\/strong&gt; Th\\u01b0\\u1edfng th\\u1ee9c tr\\u1ef1c ti\\u1ebfp. L\\u01b0u \\u00fd ki\\u1ec3m tra th\\u00e0nh ph\\u1ea7n n\\u1ebfu b\\u1ea1n c\\u00f3 d\\u1ecb \\u1ee9ng v\\u1edbi b\\u1ea5t k\\u1ef3 lo\\u1ea1i h\\u1ea1t ho\\u1eb7c tr\\u00e1i c\\u00e2y n\\u00e0o.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;13:1-13:73&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;strong&gt;M\\u1ee9t T\\u1ebft organic:&lt;\\/strong&gt; D\\u00f9ng tr\\u1ef1c ti\\u1ebfp ho\\u1eb7c k\\u1ebft h\\u1ee3p v\\u1edbi b\\u00e1nh m\\u00ec, b\\u00e1nh quy.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;14:1-15:0&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;strong&gt;H\\u1ea1t dinh d\\u01b0\\u1ee1ng &amp; tr\\u00e1i c\\u00e2y s\\u1ea5y:&lt;\\/strong&gt; D\\u00f9ng tr\\u1ef1c ti\\u1ebfp nh\\u01b0 m\\u00f3n \\u0103n v\\u1eb7t ho\\u1eb7c th\\u00eam v\\u00e0o c\\u00e1c m\\u00f3n \\u0103n kh\\u00e1c nh\\u01b0 salad, s\\u1eefa chua.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n&lt;\\/ul&gt;\\r\\n\\r\\n&lt;p data-sourcepos=&quot;16:1-16:25&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;&lt;strong&gt;3. L\\u01b0u \\u00fd khi s\\u1eed d\\u1ee5ng:&lt;\\/strong&gt;&lt;\\/span&gt;&lt;\\/p&gt;\\r\\n\\r\\n&lt;ul data-sourcepos=&quot;18:1-22:0&quot;&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;18:1-18:56&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;Ki\\u1ec3m tra h\\u1ea1n s\\u1eed d\\u1ee5ng c\\u1ee7a t\\u1eebng s\\u1ea3n ph\\u1ea9m tr\\u01b0\\u1edbc khi d\\u00f9ng.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;19:1-19:76&quot; style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16px;&quot;&gt;B\\u1ea3o qu\\u1ea3n c\\u00e1c s\\u1ea3n ph\\u1ea9m \\u1edf n\\u01a1i kh\\u00f4 r\\u00e1o, tho\\u00e1ng m\\u00e1t, tr\\u00e1nh \\u00e1nh n\\u1eafng tr\\u1ef1c ti\\u1ebfp.&lt;\\/span&gt;&lt;\\/li&gt;\\r\\n\\t&lt;li data-sourcepos=&quot;20:1-20:69&quot; style=&quot;text-al