,NULL,NULL,'Hộp Bánh Trung Thu Kim Long Ngọc Phụng','',0,0,0,4,'stock,hienthi','san-pham',1729783142,'2024-10-24 15:19:02','2025-08-08 15:41:45',1730692201,204,'hop-banh-trung-thu-kim-long-ngoc-phung-2-1729783142.jpg','2024-11-04 03:50:01'),(370,'37','0','22',NULL,0,'hop-banh-trung-thu-lam-nguyet-phu-quy-2-1729783504.jpg',NULL,NULL,'29,28','9','hop-banh-trung-thu-lam-nguyet-phu-quy','',NULL,'&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:17.5pt; font-variant:normal; white-space:pre-wrap&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#555555&quot;&gt;&lt;span style=&quot;font-weight:700&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Hộp Bánh Trung Thu Lam Nguyệt Phú Quý – Mang Đến Phúc Lành, Thịnh Vượng Cho Mùa Tết Đoàn Viên&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;text-align:center&quot;&gt;&lt;img alt=&quot;&quot; height=&quot;1135&quot; src=&quot;https://sonagift.vn/upload/filemanager/files/hop-banh-trung-thu-lam-nguyet-phu-quy-c1.png&quot; width=&quot;1600&quot; /&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;text-align: justify;&quot;&gt; &lt;/p&gt;\r\n\r\n&lt;p style=&quot;line-height: 1.38; background-color: rgb(255, 255, 255); padding: 0pt 0pt 8pt; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:11pt; font-variant:normal; white-space:pre-wrap&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#777777&quot;&gt;&lt;span style=&quot;font-weight:400&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Lam Nguyệt Phú Quý không chỉ là một hộp bánh trung thu, mà còn là biểu tượng của sự phúc lành, thịnh vượng và hạnh phúc viên mãn. Ánh trăng dịu dàng soi rọi khắp muôn nơi, đám trẻ rước lân vui vẻ mang theo ý nghĩa tốt đẹp về sự đoàn viên và sum họp. Khi trao tặng hộp bánh này, bạn không chỉ gửi gắm tình cảm chân thành mà còn mang đến niềm vui, sự ấm áp và những khoảnh khắc ý nghĩa cho người nhận. Với “Lam Nguyệt Phú Quý”, SONA cam kết mang đến cho bạn và người thân những giá trị đích thực của sự sang trọng, đẳng cấp, hiện đại và tinh tế, góp phần làm nên một mùa Trung Thu thật ý nghĩa và trọn vẹn.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;h3 style=&quot;line-height: 1.38; background-color: rgb(255, 255, 255); padding: 0pt 0pt 7pt; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16.5pt; font-variant:normal; white-space:pre-wrap&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#555555&quot;&gt;&lt;span style=&quot;font-weight:700&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Tìm kiếm sự tinh tế và sang trọng cho hộp quà Trung Thu năm nay?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;\r\n\r\n&lt;p style=&quot;line-height: 1.38; background-color: rgb(255, 255, 255); padding: 0pt 0pt 8pt; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:11pt; font-variant:normal; white-space:pre-wrap&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#777777&quot;&gt;&lt;span style=&quot;font-weight:400&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Hãy khám phá Hộp Bánh Trung Thu Lam Nguyệt Phú Quý – Biểu tượng của sự may mắn, thịnh vượng và hạnh phúc viên mãn.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;h3 style=&quot;line-height: 1.38; background-color: rgb(255, 255, 255); margin-bottom: 9px; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:16.5pt; font-variant:normal; white-space:pre-wrap&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#555555&quot;&gt;&lt;span style=&quot;font-weight:700&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Thiết kế sang trọng, đẳng cấp:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;\r\n\r\n&lt;ul&gt;\r\n	&lt;li aria-level=&quot;1&quot; style=&quot;list-style-type: disc; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:11pt; font-variant:normal; white-space:pre-wrap&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#777777&quot;&gt;&lt;span style=&quot;font-weight:400&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Hộp chủ nhật màu xanh biển óng ánh, in nổi tên thương hiệu và hoa văn tinh tế&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n	&lt;li aria-level=&quot;1&quot; style=&quot;list-style-type: disc; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:11pt; font-variant:normal; white-space:pre-wrap&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#777777&quot;&gt;&lt;span style=&quot;font-weight:400&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Tông màu chủ đạo sang trọng, thu hút mọi ánh nhìn&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;\r\n	&lt;li aria-level=&quot;1&quot; style=&quot;list-style-type: disc; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:11pt; font-variant:normal; white-space:pre-wrap&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#777777&quot;&gt;&lt;span style=&quot;font-weight:400&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Bao bì cao cấp, thích hợp làm quà t